pm.test("/certified_products/{certifiedProductId} end point response should have promotingInteroperabilityUserHistory data", function () {
    var jsonData = pm.response.json();
    pm.response.to.have.status(200);
    pm.expect(jsonData).to.have.property("promotingInteroperabilityUserHistory");
    pm.expect(jsonData.promotingInteroperabilityUserHistory[0]).to.have.property('id');
    pm.expect(jsonData.promotingInteroperabilityUserHistory[0]).to.have.property('userCount');
    pm.expect(jsonData.promotingInteroperabilityUserHistory[0]).to.have.property('userCountDate');
});

